		local targetName = script.Parent.Parent.Parent.User.Text
		if targetName == "" or targetName == "User" then
			targetName = script.Parent.Parent.Parent["SELECTED PLAYER"].Text
		end

		-- Verify the target exists in workspace before proceeding
		local plrtotpto = workspace:FindFirstChild(targetName)
		if not plrtotpto or not plrtotpto:FindFirstChild("HumanoidRootPart") then
			warn("[VOID WARE]: Target player or their HumanoidRootPart could not be found.")
			print("[VOID WARE]: Trying to find PrimaryPart/Head")
			local cloneGroup = workspace:FindFirstChild("Clones") and workspace.Clones:FindFirstChild(script.Parent.Parent.Parent.Parent.Cloneparent.Value)
			if cloneGroup then
				local findclone = cloneGroup:FindFirstChild(targetName)
				if findclone and (findclone:FindFirstChild("HumanoidRootPart") or findclone.PrimaryPart) then
					plrtotpto = findclone
				else
					warn("[VOID WARE]: STOPPED FLING BECAUSE THERE IS NO TARGET/TARGET PARTS ARE NOT FOUND")
					return
				end
			else
				warn("[VOID WARE]: STOPPED FLING BECAUSE THERE IS NO TARGET/TARGET PARTS ARE NOT FOUND")
				return
			end
		end

		if offon and hrp.Position.Y <= 1000 then

			-- Disable character collision safely
			for _, v in pairs(char:GetChildren()) do
				if v:IsA("BasePart") then
					v.CanCollide = (v.Name == "HumanoidRootPart")
				end
			end

			-- Loop sequence
			while offon and hrp.Position.Y <= 1000 and (plrtotpto:FindFirstChild("HumanoidRootPart") or plrtotpto.PrimaryPart) do
