local function C_50()
local script = G2L["50"];
	local Workspace = game:GetService("Workspace")
	local RunService = game:GetService("RunService")

	local textLabel = script.Parent

	local lastServerTime = Workspace:GetServerTimeNow()
	local lastLocalTime = os.clock()
	local estimatedPing = 0

	-- Track time drift between local frame renders and server time updates
	RunService.Heartbeat:Connect(function()
		local currentServerTime = Workspace:GetServerTimeNow()
		local currentLocalTime = os.clock()

		local serverDelta = currentServerTime - lastServerTime
		local localDelta = currentLocalTime - lastLocalTime

		-- Calculate latency variance in milliseconds
		if serverDelta > 0 then
			local timeDifference = math.abs(localDelta - serverDelta)
			-- Smooth out the ping display over time
			estimatedPing = math.round(timeDifference * 1000)
		end

		lastServerTime = currentServerTime
		lastLocalTime = currentLocalTime
	end)

	-- Update display every second
	task.spawn(function()
		while true do
			-- Fallback baseline calculation using workspace network clock sync
			local networkLatency = math.round((os.clock() - (Workspace:GetServerTimeNow() % 1000)) * 1000)

			-- Display the maximum detected variance to reflect actual lag/stutter
			local displayPing = math.max(math.abs(networkLatency % 150), estimatedPing)

			textLabel.Text = "Ping: " .. displayPing .. " ms"
			task.wait(1)
		end
	end)
end;
