		activeValue.Parent = button
	end

	local currentAura = nil

	local function stopAura()
		activeValue.Value = false
		if currentAura then
			currentAura:Destroy()
			currentAura = nil
		end
	end

	-- Stop when pressing "R"
	keyboard.InputBegan:Connect(function(input, gameProcessed)
		if gameProcessed then return end
		if input.KeyCode == Enum.KeyCode.R then
			stopAura()
		end
